47	public class PipeTransferTabletRawReq extends TPipeTransferReq {
48	
49	  private static final Logger LOGGER = LoggerFactory.getLogger(PipeTransferTabletRawReq.class);
50	
51	  protected transient Tablet tablet;
52	  protected transient boolean isAligned;
53	
54	  public Tablet getTablet() {
55	    return tablet;
56	  }
57	
58	  public boolean getIsAligned() {
59	    return isAligned;
60	  }
61	
62	  public InsertTabletStatement constructStatement() {
63	    new PipeTabletEventSorter(tablet).deduplicateAndSortTimestampsIfNecessary();
64	
65	    try {
66	      if (isTabletEmpty(tablet)) {
67	        // Empty statement, will be filtered after construction
68	        return new InsertTabletStatement();
69	      }
70	
71	      final TSInsertTabletReq request = new TSInsertTabletReq();
72	
73	      for (final IMeasurementSchema measurementSchema : tablet.getSchemas()) {
74	        request.addToMeasurements(measurementSchema.getMeasurementName());
75	        request.addToTypes(measurementSchema.getType().ordinal());
76	      }
77	
78	      request.setPrefixPath(tablet.getDeviceId());
79	      request.setIsAligned(isAligned);
80	      request.setTimestamps(SessionUtils.getTimeBuffer(tablet));
81	      request.setValues(SessionUtils.getValueBuffer(tablet));
82	      request.setSize(tablet.getRowSize());
83	      request.setMeasurements(
84	          PathUtils.checkIsLegalSingleMeasurementsAndUpdate(request.getMeasurements()));
85	
86	      return StatementGenerator.createStatement(request);
87	    } catch (final MetadataException e) {
88	      LOGGER.warn("Generate Statement from tablet {} error.", tablet, e);
89	      return null;
90	    }
91	  }
92	
93	  /////////////////////////////// WriteBack & Batch ///////////////////////////////
94	
95	  public static PipeTransferTabletRawReq toTPipeTransferRawReq(
96	      final Tablet tablet, final boolean isAligned) {
97	    final PipeTransferTabletRawReq tabletReq = new PipeTransferTabletRawReq();
98	
99	    tabletReq.tablet = tablet;
100	    tabletReq.isAligned = isAligned;
101	
102	    return tabletReq;
103	  }
104	
105	  /////////////////////////////// Thrift ///////////////////////////////
106	
107	  public static PipeTransferTabletRawReq toTPipeTransferReq(
108	      final Tablet tablet, final boolean isAligned) throws IOException {
109	    final PipeTransferTabletRawReq tabletReq = new PipeTransferTabletRawReq();
110	
111	    tabletReq.tablet = tablet;
112	    tabletReq.isAligned = isAligned;
113	
114	    tabletReq.version = IoTDBConnectorRequestVersion.VERSION_1.getVersion();
115	    tabletReq.type = PipeRequestType.TRANSFER_TABLET_RAW.getType();
116	    try (final PublicBAOS byteArrayOutputStream = new PublicBAOS();
117	        final DataOutputStream outputStream = new DataOutputStream(byteArrayOutputStream)) {
118	      tablet.serialize(outputStream);
119	      ReadWriteIOUtils.write(isAligned, outputStream);
120	      tabletReq.body =
121	          ByteBuffer.wrap(byteArrayOutputStream.getBuf(), 0, byteArrayOutputStream.size());
122	    }
123	
124	    return tabletReq;
125	  }
126	
127	  public static PipeTransferTabletRawReq fromTPipeTransferReq(final TPipeTransferReq transferReq) {
128	    final PipeTransferTabletRawReq tabletReq = new PipeTransferTabletRawReq();
129	
130	    tabletReq.tablet = Tablet.deserialize(transferReq.body);
131	    tabletReq.isAligned = ReadWriteIOUtils.readBool(transferReq.body);
132	
133	    tabletReq.version = transferReq.version;
134	    tabletReq.type = transferReq.type;
135	    tabletReq.body = transferReq.body;
136	
137	    return tabletReq;
138	  }
139	
140	  /////////////////////////////// Air Gap ///////////////////////////////
141	
142	  public static byte[] toTPipeTransferBytes(final Tablet tablet, final boolean isAligned)
143	      throws IOException {
144	    try (final PublicBAOS byteArrayOutputStream = new PublicBAOS();
145	        final DataOutputStream outputStream = new DataOutputStream(byteArrayOutputStream)) {
146	      ReadWriteIOUtils.write(IoTDBConnectorRequestVersion.VERSION_1.getVersion(), outputStream);
147	      ReadWriteIOUtils.write(PipeRequestType.TRANSFER_TABLET_RAW.getType(), outputStream);
148	      tablet.serialize(outputStream);
149	      ReadWriteIOUtils.write(isAligned, outputStream);
150	      return byteArrayOutputStream.toByteArray();
151	    }
152	  }
153	
154	  /////////////////////////////// Object ///////////////////////////////
155	
156	  @Override
157	  public boolean equals(final Object obj) {
158	    if (this == obj) {
159	      return true;
160	    }
161	    if (obj == null || getClass() != obj.getClass()) {
162	      return false;
163	    }
164	    final PipeTransferTabletRawReq that = (PipeTransferTabletRawReq) obj;
165	    return Objects.equals(tablet, that.tablet)
166	        && isAligned == that.isAligned
167	        && version == that.version
168	        && type == that.type
169	        && Objects.equals(body, that.body);
170	  }
171	
172	  @Override
173	  public int hashCode() {
174	    return Objects.hash(tablet, isAligned, version, type, body);
175	  }
