77	      request.setTimestamps(SessionUtils.getTimeBuffer(tablet));
78	      request.setValues(SessionUtils.getValueBuffer(tablet));
79	      request.setSize(tablet.getRowSize());
80	
81	      // Tree model
82	      if (Objects.isNull(dataBaseName)) {
83	        request.setMeasurements(
84	            PathUtils.checkIsLegalSingleMeasurementsAndUpdate(request.getMeasurements()));
85	        return StatementGenerator.createStatement(request);
86	      }
87	
88	      // Table model
89	      request.setWriteToTable(true);
90	      request.columnCategories =
91	          tablet.getColumnTypes().stream()
92	              .map(t -> (byte) t.ordinal())
93	              .collect(Collectors.toList());
94	      final InsertTabletStatement statement = StatementGenerator.createStatement(request);
95	      statement.setDatabaseName(dataBaseName);
96	      return statement;
97	    } catch (final MetadataException e) {
98	      LOGGER.warn("Generate Statement from tablet {} error.", tablet, e);
99	      return null;
100	    }
101	  }
