82	  public void generateData(final String tableName, final int number, final long timeGap)
83	      throws IOException, WriteProcessException {
84	    final List<IMeasurementSchema> schemas = table2MeasurementSchema.get(tableName);
85	    final List<ColumnCategory> columnCategoryList = table2ColumnCategory.get(tableName);
86	    int timeIndex = -1;
87	    for (int i = 0; i < columnCategoryList.size(); ++i) {
88	      if (columnCategoryList.get(i) == ColumnCategory.TIME) {
89	        timeIndex = i;
90	        break;
91	      }
92	    }
93	    final List<IMeasurementSchema> schemaWithoutTime = new ArrayList<>(schemas);
94	    final List<ColumnCategory> columnCategoriesWithoutTime = new ArrayList<>(columnCategoryList);
95	    if (timeIndex > -1) {
96	      schemaWithoutTime.remove(timeIndex);
97	      columnCategoriesWithoutTime.remove(timeIndex);
98	    }
99	    final List<String> columnNameList =
100	        schemaWithoutTime.stream()
101	            .map(IMeasurementSchema::getMeasurementName)
102	            .collect(Collectors.toList());
103	    final List<TSDataType> dataTypeList =
104	        schemaWithoutTime.stream().map(IMeasurementSchema::getType).collect(Collectors.toList());
105	    final TreeSet<Long> timeSet = table2TimeSet.get(tableName);
106	    final Tablet tablet =
107	        new Tablet(tableName, columnNameList, dataTypeList, columnCategoriesWithoutTime);
108	    final long sensorNum = schemaWithoutTime.size();
109	    long startTime = timeSet.isEmpty() ? 0L : timeSet.last();
110	
111	    for (long r = 0; r < number; r++) {
112	      final int row = tablet.getRowSize();
113	      startTime += timeGap;
114	      tablet.addTimestamp(row, startTime);
115	      timeSet.add(startTime);
116	      for (int i = 0; i < sensorNum; i++) {
117	        generateDataPoint(tablet, i, row, schemaWithoutTime.get(i));
118	      }
119	      // write
120	      if (tablet.getRowSize() == tablet.getMaxRowNumber()) {
121	        writer.writeTable(tablet);
122	        tablet.reset();
123	      }
124	    }
125	    // write
126	    if (tablet.getRowSize() != 0) {
127	      writer.writeTable(tablet);
128	      tablet.reset();
129	    }
130	
131	    LOGGER.info("Write {} points into table {}", number, tableName);
132	  }
