135	      final Tablet tablet, final int column, final int row, final IMeasurementSchema schema) {
136	    switch (schema.getType()) {
137	      case INT32:
138	        generateINT32(tablet, column, row);
139	        break;
140	      case DATE:
141	        generateDATE(tablet, column, row);
142	        break;
143	      case INT64:
144	      case TIMESTAMP:
145	        generateINT64(tablet, column, row);
146	        break;
147	      case FLOAT:
148	        generateFLOAT(tablet, column, row);
149	        break;
