151	        generateDOUBLE(tablet, column, row);
152	        break;
153	      case BOOLEAN:
154	        generateBOOLEAN(tablet, column, row);
155	        break;
156	      case TEXT:
157	      case BLOB:
158	      case STRING:
159	        generateTEXT(tablet, column, row);
160	        break;
