43	public class TsFileTableGenerator implements AutoCloseable {
44	  private static final Logger LOGGER = LoggerFactory.getLogger(TsFileTableGenerator.class);
45	
46	  private final File tsFile;
47	  private final TsFileWriter writer;
48	  private final Map<String, TreeSet<Long>> table2TimeSet;
49	  private final Map<String, List<IMeasurementSchema>> table2MeasurementSchema;
50	  private final Map<String, List<Tablet.ColumnCategory>> table2ColumnCategory;
51	  private Random random;
52	
53	  public TsFileTableGenerator(final File tsFile) throws IOException {
54	    this.tsFile = tsFile;
55	    this.writer = new TsFileWriter(tsFile);
56	    this.table2TimeSet = new HashMap<>();
57	    this.table2MeasurementSchema = new HashMap<>();
58	    this.table2ColumnCategory = new HashMap<>();
59	    this.random = new Random();
60	  }
61	
62	  public void registerTable(
63	      final String tableName,
64	      final List<IMeasurementSchema> columnSchemasList,
65	      final List<Tablet.ColumnCategory> columnCategoryList) {
66	    if (table2MeasurementSchema.containsKey(tableName)) {
67	      LOGGER.warn("Table {} already exists", tableName);
68	      return;
69	    }
70	
71	    writer.registerTableSchema(new TableSchema(tableName, columnSchemasList, columnCategoryList));
72	    table2TimeSet.put(tableName, new TreeSet<>());
73	    table2MeasurementSchema.put(tableName, columnSchemasList);
74	    table2ColumnCategory.put(tableName, columnCategoryList);
75	  }
76	
77	  public void generateData(
78	      final String tableName, final int number, final long timeGap, final boolean isAligned)
79	      throws IOException, WriteProcessException {
80	    final List<IMeasurementSchema> schemas = table2MeasurementSchema.get(tableName);
81	    final List<String> columnNameList =
82	        schemas.stream().map(IMeasurementSchema::getMeasurementName).collect(Collectors.toList());
83	    final List<TSDataType> dataTypeList =
84	        schemas.stream().map(IMeasurementSchema::getType).collect(Collectors.toList());
85	    final List<Tablet.ColumnCategory> columnCategoryList = table2ColumnCategory.get(tableName);
86	    final TreeSet<Long> timeSet = table2TimeSet.get(tableName);
87	    final Tablet tablet = new Tablet(tableName, columnNameList, dataTypeList, columnCategoryList);
88	    final Object[] values = tablet.values;
89	    final long sensorNum = schemas.size();
90	    long startTime = timeSet.isEmpty() ? 0L : timeSet.last();
91	
92	    for (long r = 0; r < number; r++) {
93	      final int row = tablet.getRowSize();
94	      startTime += timeGap;
95	      tablet.addTimestamp(row, startTime);
96	      timeSet.add(startTime);
97	      for (int i = 0; i < sensorNum; i++) {
98	        generateDataPoint(values[i], row, schemas.get(i));
99	      }
100	      // write
101	      if (tablet.getRowSize() == tablet.getMaxRowNumber()) {
102	        if (!isAligned) {
103	          writer.writeTable(tablet);
104	        } else {
105	          writer.writeAligned(tablet);
106	        }
107	        tablet.reset();
108	      }
109	    }
110	    // write
111	    if (tablet.getRowSize() != 0) {
112	      if (!isAligned) {
113	        writer.writeTable(tablet);
114	      } else {
115	        writer.writeAligned(tablet);
116	      }
117	      tablet.reset();
118	    }
119	
120	    LOGGER.info("Write {} points into table {}", number, tableName);
121	  }
122	
123	  private void generateDataPoint(final Object obj, final int row, final IMeasurementSchema schema) {
124	    switch (schema.getType()) {
125	      case INT32:
126	        generateINT32(obj, row);
127	        break;
128	      case DATE:
129	        generateDATE(obj, row);
130	        break;
131	      case INT64:
132	      case TIMESTAMP:
133	        generateINT64(obj, row);
134	        break;
135	      case FLOAT:
136	        generateFLOAT(obj, row);
137	        break;
138	      case DOUBLE:
139	        generateDOUBLE(obj, row);
140	        break;
141	      case BOOLEAN:
142	        generateBOOLEAN(obj, row);
143	        break;
144	      case TEXT:
145	      case BLOB:
146	      case STRING:
147	        generateTEXT(obj, row);
148	        break;
149	      default:
150	        LOGGER.error("Wrong data type {}.", schema.getType());
151	    }
152	  }
153	
154	  private void generateINT32(final Object obj, final int row) {
155	    final int[] ints = (int[]) obj;
156	    ints[row] = random.nextInt();
157	  }
158	
159	  private void generateDATE(final Object obj, final int row) {
160	    final LocalDate[] dates = (LocalDate[]) obj;
161	    dates[row] =
162	        LocalDate.of(1000 + random.nextInt(9000), 1 + random.nextInt(12), 1 + random.nextInt(28));
163	  }
164	
165	  private void generateINT64(final Object obj, final int row) {
166	    final long[] longs = (long[]) obj;
167	    longs[row] = random.nextLong();
168	  }
169	
170	  private void generateFLOAT(final Object obj, final int row) {
171	    final float[] floats = (float[]) obj;
172	    floats[row] = random.nextFloat();
173	  }
174	
175	  private void generateDOUBLE(final Object obj, final int row) {
176	    final double[] doubles = (double[]) obj;
177	    doubles[row] = random.nextDouble();
178	  }
179	
180	  private void generateBOOLEAN(final Object obj, final int row) {
181	    final boolean[] booleans = (boolean[]) obj;
182	    booleans[row] = random.nextBoolean();
183	  }
184	
185	  private void generateTEXT(final Object obj, final int row) {
186	    final Binary[] binaries = (Binary[]) obj;
187	    binaries[row] =
188	        new Binary(String.format("test point %d", random.nextInt()), TSFileConfig.STRING_CHARSET);
189	  }
190	
191	  public long getTotalNumber() {
192	    return table2TimeSet.entrySet().stream()
193	        .mapToInt(
194	            entry -> entry.getValue().size() * table2MeasurementSchema.get(entry.getKey()).size())
195	        .sum();
196	  }
197	
198	  @Override
199	  public void close() throws Exception {
200	    writer.close();
201	  }
202	}
